python - <<'PY'
from pynwb import NWBHDF5IO
import numpy as np
path='/app/data/sub-m11/sub-m11_ses-03_behavior+ophys.nwb'
with NWBHDF5IO(path,'r',load_namespaces=True) as io:
    nwb=io.read()
    for pname,pmod in nwb.processing.items():
        print('\nPROCESSING', pname)
        for iname, iface in pmod.data_interfaces.items():
            print(' interface', iname, type(iface).__name__)
            if hasattr(iface,'time_series'):
                print('  ts keys', list(iface.time_series.keys()))
            if hasattr(iface,'spatial_series'):
                print('  spatial keys', list(iface.spatial_series.keys()))
            if hasattr(iface,'roi_response_series'):
                print('  roi_response_series', list(iface.roi_response_series.keys()))
    beh = nwb.processing['behavior']
    for name, iface in beh.data_interfaces.items():
        if hasattr(iface,'time_series'):
            for tsname, ts in iface.time_series.items():
                data = ts.data
                try:
                    shape = data.shape
                except Exception:
                    shape = np.asarray(data[:]).shape
                print('behavior ts', name, tsname, 'shape', shape, 'unit', getattr(ts,'unit',None), 'rate', getattr(ts,'rate',None), 'timestamps', ts.timestamps is not None)
    ophys = nwb.processing['ophys']
    for name, iface in ophys.data_interfaces.items():
        print('ophys iface', name, type(iface).__name__)
        if hasattr(iface,'roi_response_series'):
            for rname, rrs in iface.roi_response_series.items():
                print('  rrs', rname, 'shape', rrs.data.shape, 'unit', getattr(rrs,'unit',None), 'rate', getattr(rrs,'rate',None), 'timestamps', rrs.timestamps is not None)
        if hasattr(iface,'plane_segmentations'):
            print('  segmentations', list(iface.plane_segmentations.keys()))
